'use strict';
/* 픽스처 — 계수기의 세 경계 (2026-08-14 · #Q70 잔여 처분의 조임). 돌아가지 않는다(파싱 재료다).
 *
 *   ⓐ SQL 제거기 «경유»는 안전, 원문 «직행»은 위험 — ㉠축 별건 판정.
 *      ㉡축(사본 합치기)의 「언어가 달라 안 합친다」는 그대로다(아래 SQL주석없이 는 SQL사본 1 로 선다).
 *   ⓑ 콜백 «매개변수»가 파일 스코프의 원문 이름을 그늘지게 하면 ❔모름 — 런타임 값이라 못 가른다
 *      (`사건위조:101` 오탐 그 모양 — 위험으로 세면 처방이 「런타임 배열을 감싸라」가 된다 F103).
 *   ⓒ 통로를 «별칭 재수출»로 받아도 정제다(`_재수출.js` 경유 — as 실행층점검 실측 · 같은 병 5차).
 *
 * 각 경계가 되돌려지면 이 뿌리의 census 가 이렇게 움직인다(회귀가 그 수를 못박는다):
 *   ⓐ 되돌림 → 안전 2→1 · 모름 1→2   ⓑ 되돌림 → 위험 1→2 · 모름 1→0   ⓒ 되돌림 → 위험 1→2 · 안전 2→1 */
const fs = require('fs');
const assert = require('assert');
const { 지우개 } = require('./_재수출.js');

const SQL주석없이 = (q) => q.replace(/\/\*[\s\S]*?\*\//g, ' ').replace(/--[^\n]*/g, ' ');

const 스키마 = fs.readFileSync('스키마.sql', 'utf8');
const 소스 = fs.readFileSync('a.js', 'utf8');

// ⓐ-1 SQL 제거기 경유 — «안전»으로 서야 한다.
assert.ok(!/on delete cascade/.test(SQL주석없이(스키마)), 'cascade 금지');
// ⓐ-2 원문 직행 — «위험» 그대로(이 뿌리의 위험 1 은 이것 하나뿐이어야 한다).
assert.ok(!/limit/i.test(스키마), 'limit 금지');

// ⓑ 콜백 매개변수 그늘 — «모름»으로 서야 한다(위 `m` 은 원문 파생이지만 이 `m` 은 런타임 값이다).
const m = /create table (\w+)/.exec(스키마);
const 결과들 = [m && m[1]];
assert.ok(!결과들.some((m) => m.includes('금지')), '이름 검사');

// ⓒ 별칭 재수출 통로 경유 — «안전»으로 서야 한다.
const 깨끗 = 지우개(소스);
assert.ok(!깨끗.includes('금지코드'), '재수출 통로 경유');
